import {products,coupons,deliveryRates} from './data.js';
export const money=n=>'S/ '+n.toFixed(2);
export const load=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
export const state={cart:load('dm-cart',[]),favorites:load('dm-favorites',[]),coupon:load('dm-coupon',''),delivery:'Recojo',district:'Miraflores'};
state.cart=Array.isArray(state.cart)?state.cart.filter(x=>products.some(p=>p.id===x.productId)&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=99):[];
export function unitPrice(item){const p=products.find(p=>p.id===item.productId);if(!p)return 0;return p.basePrice+(p.sizes.find(x=>x.name===item.size)?.extra||0)+(p.decorations.find(x=>x.name===item.decoration)?.extra||0)}
export function totals(){const subtotal=state.cart.reduce((s,i)=>s+unitPrice(i)*i.quantity,0);const discount=Math.round(subtotal*(coupons[state.coupon]||0)*100)/100;const deliveryCost=state.delivery==='Delivery'&&subtotal?(deliveryRates[state.district]??20):0;return {subtotal,discount,deliveryCost,total:Math.round((subtotal-discount+deliveryCost)*100)/100}}
export function save(){localStorage.setItem('dm-cart',JSON.stringify(state.cart));localStorage.setItem('dm-favorites',JSON.stringify(state.favorites));localStorage.setItem('dm-coupon',JSON.stringify(state.coupon));window.dispatchEvent(new Event('cartchange'))}
export function addItem(productId,options={}){const p=products.find(x=>x.id===productId);if(!p)throw Error('Producto no encontrado');const i={productId,size:options.size||'Pequeño',flavor:options.flavor||p.flavors[0],decoration:options.decoration||'Clásica',message:options.message||'',occasion:options.occasion||'Reunión',quantity:Number(options.quantity??1)};if(!p.sizes.some(s=>s.name===i.size)||!p.flavors.includes(i.flavor)||!p.decorations.some(d=>d.name===i.decoration)||!Number.isInteger(i.quantity)||i.quantity<1||i.quantity>99)throw Error('Configuración inválida');const key=JSON.stringify({...i,quantity:0});const found=state.cart.find(x=>x.key===key);if(found)found.quantity=Math.min(99,found.quantity+i.quantity);else state.cart.push({...i,key});save();return i}
export function applyCoupon(code){code=code.trim().toUpperCase();if(!coupons[code])return false;state.coupon=code;save();return true}
export function minimumDate(){const d=new Date();d.setDate(d.getDate()+2);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
